create type public.house_rules_status as enum ('DRAFT','ACTIVE','ARCHIVED');
create table public.house_rules_versions(id uuid primary key default gen_random_uuid(),administration_id uuid not null references public.administrations(id) on delete cascade,property_id uuid not null references public.properties(id) on delete cascade,version_number int not null check(version_number>0),title text not null default 'Reglas de convivencia',content jsonb not null,status public.house_rules_status not null default 'DRAFT',effective_from date,created_by_person_id uuid references public.people(id) on delete set null,created_at timestamptz not null default now(),unique(property_id,version_number));
create unique index house_rules_one_active_uq on public.house_rules_versions(property_id) where status='ACTIVE';
create index house_rules_admin_idx on public.house_rules_versions(administration_id);
alter table public.house_rules_versions enable row level security; grant select on public.house_rules_versions to authenticated; revoke insert,update,delete on public.house_rules_versions from anon,authenticated;
create policy house_rules_select on public.house_rules_versions for select to authenticated using(public.is_administration_member(administration_id) or exists(select 1 from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where rm.property_id=house_rules_versions.property_id and public.can_view_relationship(r.id)));
create or replace function public.create_property_space(p_property_id uuid,p_space_type text,p_name text default null,p_description text default null) returns public.property_spaces language plpgsql security definer set search_path='' as $$ declare p public.properties; s public.property_spaces; begin select * into p from public.properties where id=p_property_id; if not found then raise exception 'PROPERTY_NOT_FOUND'; end if; if public.can_manage_administration(p.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if p.rental_mode<>'BY_ROOMS' then raise exception 'SHARED_SPACES_REQUIRE_ROOM_RENTAL'; end if; insert into public.property_spaces(administration_id,property_id,space_type,name,description) values(p.administration_id,p.id,upper(btrim(p_space_type)),nullif(btrim(p_name),''),nullif(btrim(p_description),'')) returning * into s; return s; end $$;
create or replace function public.set_room_space_access(p_room_id uuid,p_property_space_id uuid,p_access_allowed boolean default true) returns public.room_space_access language plpgsql security definer set search_path='' as $$ declare r public.rooms; s public.property_spaces; x public.room_space_access; begin select * into r from public.rooms where id=p_room_id; if not found then raise exception 'ROOM_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; select * into s from public.property_spaces where id=p_property_space_id; if not found or s.property_id<>r.property_id or s.administration_id<>r.administration_id then raise exception 'SPACE_ROOM_PROPERTY_MISMATCH'; end if; insert into public.room_space_access(room_id,property_space_id,access_allowed) values(r.id,s.id,p_access_allowed) on conflict(room_id,property_space_id) do update set access_allowed=excluded.access_allowed returning * into x; return x; end $$;
create or replace function public.publish_house_rules(p_property_id uuid,p_title text,p_content jsonb,p_effective_from date default current_date) returns public.house_rules_versions language plpgsql security definer set search_path='' as $$ declare p public.properties; v public.house_rules_versions; n int; actor uuid; begin select * into p from public.properties where id=p_property_id; if not found then raise exception 'PROPERTY_NOT_FOUND'; end if; if public.can_manage_administration(p.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if p.rental_mode<>'BY_ROOMS' then raise exception 'HOUSE_RULES_REQUIRE_ROOM_RENTAL'; end if; if p_content is null or p_content='null'::jsonb then raise exception 'HOUSE_RULES_CONTENT_REQUIRED'; end if; select coalesce(max(version_number),0)+1 into n from public.house_rules_versions where property_id=p.id for update; update public.house_rules_versions set status='ARCHIVED' where property_id=p.id and status='ACTIVE'; select person_id into actor from public.accounts where auth_user_id=auth.uid(); insert into public.house_rules_versions(administration_id,property_id,version_number,title,content,status,effective_from,created_by_person_id) values(p.administration_id,p.id,n,coalesce(nullif(btrim(p_title),''),'Reglas de convivencia'),p_content,'ACTIVE',p_effective_from,actor) returning * into v; return v; end $$;
create or replace function public.accept_house_rules(p_rules_version_id uuid,p_relationship_id uuid) returns public.acceptances language plpgsql security definer set search_path='' as $$ declare v public.house_rules_versions; person uuid; a public.acceptances; begin select * into v from public.house_rules_versions where id=p_rules_version_id; if not found then raise exception 'HOUSE_RULES_NOT_FOUND'; end if; if v.status<>'ACTIVE' then raise exception 'HOUSE_RULES_NOT_ACTIVE'; end if; select person_id into person from public.accounts where auth_user_id=auth.uid(); if person is null then raise exception 'ACCOUNT_REQUIRED'; end if; if not exists(select 1 from public.rental_participants rp join public.rental_relationship_subjects rs on rs.rental_relationship_id=rp.rental_relationship_id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where rp.rental_relationship_id=p_relationship_id and rp.person_id=person and rp.status='ACTIVE' and rp.participation_type in('TENANT','OCCUPANT') and rm.property_id=v.property_id) then raise exception 'NOT_ACTIVE_RESIDENT_FOR_PROPERTY'; end if; if exists(select 1 from public.acceptances x where x.person_id=person and x.rental_relationship_id=p_relationship_id and x.document_type='HOUSE_RULES' and x.subject_id=v.id) then raise exception 'HOUSE_RULES_ALREADY_ACCEPTED'; end if; insert into public.acceptances(administration_id,person_id,rental_relationship_id,document_type,document_version,purpose,subject_type,subject_id,accepted_at,method,evidence) values(v.administration_id,person,p_relationship_id,'HOUSE_RULES',v.version_number::text,'ACCEPT_HOUSE_RULES','HOUSE_RULES_VERSION',v.id,now(),'AUTHENTICATED_ACTION',jsonb_build_object('rules_version_id',v.id)) returning * into a; return a; end $$;
create or replace function public.add_relationship_occupant(p_relationship_id uuid,p_person_id uuid,p_starts_on date default current_date,p_ends_on date default null) returns public.rental_participants language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; x public.rental_participants; begin select * into r from public.rental_relationships where id=p_relationship_id; if not found then raise exception 'RENTAL_RELATIONSHIP_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if r.status not in('DRAFT','ACTIVE','ENDING') then raise exception 'RENTAL_NOT_OPEN_FOR_OCCUPANTS'; end if; if p_ends_on is not null and p_ends_on<p_starts_on then raise exception 'INVALID_OCCUPANT_DATES'; end if; insert into public.rental_participants(rental_relationship_id,person_id,participation_type,status,starts_on,ends_on) values(r.id,p_person_id,'OCCUPANT',case when p_ends_on is not null and p_ends_on<current_date then 'ENDED' else 'ACTIVE' end,p_starts_on,p_ends_on) returning * into x; return x; end $$;
revoke all on function public.create_property_space(uuid,text,text,text),public.set_room_space_access(uuid,uuid,boolean),public.publish_house_rules(uuid,text,jsonb,date),public.accept_house_rules(uuid,uuid),public.add_relationship_occupant(uuid,uuid,date,date) from public,anon; grant execute on function public.create_property_space(uuid,text,text,text),public.set_room_space_access(uuid,uuid,boolean),public.publish_house_rules(uuid,text,jsonb,date),public.accept_house_rules(uuid,uuid),public.add_relationship_occupant(uuid,uuid,date,date) to authenticated,service_role;